DROP TABLE IF EXISTS tb_municip;
CREATE TABLE tb_municip (
  co_municip CHAR(6),
  co_municdv CHAR(1),
  co_status CHAR(1),
  ds_nome CHAR(41),
  sg_uf CHAR(2),
  in_capital CHAR(1),
  in_amazleg CHAR(1),
  in_semiar CHAR(1),
  in_frontzn CHAR(1),
  dt_instal CHAR(4),
  dt_extin CHAR(4),
  co_sucess CHAR(6),
  nu_latitud CHAR(19),
  nu_longit CHAR(17),
  nu_altitud CHAR(4),
  nu_area CHAR(10));
